    return newcclosure(function() return end)
end)

local norad = true
local no_rad; no_rad = hookmetamethod(game, "__namecall", function(self, ...)
    if norad and getnamecallmethod() == "FireServer" and self.Name == "EnteredRadiationZone" then return end
    return no_rad(self, ...)
end)
